    "SubscribeObjectEventRequest": {
      "name": "SubscribeObjectEventRequest",
      "title": "Subscribe to space, device-space relationship, and automation object events",
      "summary": "Incrementally adds object-event subscriptions for the current WebSocket session; duplicate subscriptions are idempotent.",
      "description": "When `objectIds` is omitted, null, or an empty array, subscribe to all currently accessible objects under the specified `eventTypes`; when non-empty, subscribe only to the specified objects.\nSubsequent subscription requests are merged with existing rules and do not overwrite previously specified object rules. Subscribing to all objects replaces the existing ID list for the same event type.\nApps may use all-object subscriptions to maintain a complete list; screen devices and third-party services typically subscribe to specified objects according to their business scope.\n",
      "examples": [
        {
          "name": "subscribeAllPreciseObjectEvents",
          "payload": {
            "type": "SubscribeObjectEventRequest",
            "version": "v1",
            "msgId": "object-subscribe-1",
            "data": [
              {
                "eventTypes": [
                  "SPACE_ADDED",
                  "SPACE_REMOVED",
                  "SPACE_UPDATED",
                  "AUTOMATION_ADDED",
                  "AUTOMATION_REMOVED",
                  "AUTOMATION_UPDATED",
                  "AUTOMATION_SPACE_UPDATED",
                  "DEVICE_SPACE_UPDATED"
                ],
                "objectIds": []
              }
            ]
          }
        },
        {
          "name": "subscribeSelectedObjects",
          "payload": {
            "type": "SubscribeObjectEventRequest",
            "version": "v1",
            "msgId": "object-subscribe-2",
            "data": [
              {
                "eventTypes": [
                  "DEVICE_SPACE_UPDATED"
                ],
                "objectIds": [
                  "device-1",
                  "device-2"
                ]
              },
              {
                "eventTypes": [
                  "AUTOMATION_REMOVED",
                  "AUTOMATION_UPDATED",
                  "AUTOMATION_SPACE_UPDATED"
                ],
                "objectIds": [
                  "automation-1"
                ]
              }
            ]
          }
        }
      ],
      "payloadSchema": {
        "type": "object",
        "required": [
          "type",
          "version",
          "msgId",
          "data"
        ],
        "properties": {
          "type": {
            "type": "string",
            "enum": [
              "SubscribeObjectEventRequest"
            ]
          },
          "version": {
            "type": "string",
            "enum": [
              "v1"
            ]
          },
          "msgId": {
            "type": "string",
            "description": "A non-empty identifier used by the request. It should remain unique at least among unfinished requests on the current connection. Normal responses correlate with the same msgId, while msgIds on server push messages are used only for link tracing, do not correspond to subscription request msgIds, and are not guaranteed to be globally unique.",
            "minLength": 1,
            "maxLength": 64
          },
          "data": {
            "type": "array",
            "minItems": 1,
            "maxItems": 100,
            "items": {
              "type": "object",
              "required": [
                "eventTypes"
              ],
              "properties": {
                "eventTypes": {
                  "type": "array",
                  "minItems": 1,
                  "uniqueItems": true,
                  "items": {
                    "type": "string",
                    "enum": [
                      "DEVICE_SPACE_UPDATED",
                      "SPACE_ADDED",
                      "SPACE_REMOVED",
                      "SPACE_UPDATED",
                      "AUTOMATION_ADDED",
                      "AUTOMATION_REMOVED",
                      "AUTOMATION_UPDATED",
                      "AUTOMATION_SPACE_UPDATED"
                    ]
                  }
                },
                "objectIds": {
                  "type": [
                    "array",
                    "null"
                  ],
                  "maxItems": 1000,
                  "uniqueItems": true,
                  "items": {
                    "type": "string",
                    "minLength": 1
                  },
                  "description": "When subscribing, omitted, null, or empty objectIds means all objects within the current permission scope; when non-empty, only the specified objects are matched.\nWhen unsubscribing, omitted, null, or empty objectIds means clearing all rules for the corresponding eventTypes; when non-empty, only the specified objects are removed.\nWithin the same WebSocket session, at most 1000 distinct objectIds may be cumulatively subscribed under each eventType.\nWhen objectIds is non-empty, the eventTypes in the same item must belong to the same object type; SPACE_ADDED and AUTOMATION_ADDED support only the all-objects semantic.\nThe protocol does not use a scope field; the all-objects semantic is represented uniformly through objectIds.\n"
                }
              }
            },
            "description": "Must contain 1 to 100 subscription items. Requests are merged incrementally by session, and duplicate subscriptions are idempotent.\nSPACE_ADDED and AUTOMATION_ADDED only allow the all-objects semantic for objectIds.\n"
          }
        }
      }
    },
